function minutos(hhmm) {
  const p = hhmm.split(":");
  return Number(p[0]) * 60 + Number(p[1]);
}

async function run() {
  const agora = now();
  const passou = (minutos(dates.format(agora, "HH:mm")) - minutos(params.horario) + 1440) % 1440;
  if (passou >= 60) return;
  const dia = dates.format(dates.addHours(agora, -passou / 60), "yyyy-MM-dd");
  if (state.get("ultimo") === dia) return;
  state.set("ultimo", dia);

  const manter = params.manter.split(",").map(s => s.trim().toLowerCase()).filter(Boolean);
  const acesas = (await ha.states({domain: "light"})).filter(l => l.state === "on" && !manter.some(k =>
    ((l.name || "") + " " + l.entity_id).toLowerCase().indexOf(k) !== -1));
  if (!acesas.length) return;
  for (const l of acesas) await ha.call({domain: "light", service: "turn_off", entity_id: l.entity_id});
  await notify.send({text: "💡 Apaguei " + (acesas.length === 1 ? "1 luz que tinha ficado acesa: " : acesas.length + " luzes que tinham ficado acesas: ") +
    acesas.map(l => l.name || l.entity_id).join(", ") + "."});
}
